export const glassStyles = "/* Approved edge-light v4; a fully opaque, useful header is the no-JS default. */\r\n.ew-glass-header .ew-header__inner {\r\n  --ew-liquid: 0;\r\n  position: relative;\r\n  border: 0;\r\n  border-radius: var(--ew-glass-radius, 29px);\r\n  background: transparent;\r\n  backdrop-filter: none;\r\n  -webkit-backdrop-filter: none;\r\n  box-shadow: 0 12px 26px -17px #122a3848, 0 2px 5px #18383a14;\r\n  touch-action: pan-y;\r\n}\r\n.ew-liquid-layers, .ew-liquid-optics, .ew-liquid-solid, .ew-liquid-rim, .ew-liquid-light {\r\n  position: absolute;\r\n  inset: 0;\r\n  border-radius: inherit;\r\n  pointer-events: none;\r\n}\r\n/* No opacity/filter on the wrapper: that would isolate the live backdrop. */\r\n.ew-liquid-layers { z-index: 0; }\r\n.ew-liquid-defs { position: absolute; width: 0; height: 0; overflow: hidden; }\r\n.ew-liquid-optics {\r\n  background: linear-gradient(155deg, var(--ew-glass-top, #ffffff26), transparent 52%, var(--ew-glass-bottom, #d1e9e412));\r\n  backdrop-filter: blur(var(--ew-glass-frost, 1.2px)) saturate(var(--ew-glass-saturation, 1.2));\r\n  -webkit-backdrop-filter: blur(var(--ew-glass-frost, 1.2px)) saturate(var(--ew-glass-saturation, 1.2));\r\n}\r\n.ew-header__inner:not([data-glass-state]) .ew-liquid-optics,\r\n.ew-header__inner[data-glass-state=\"solid\"] .ew-liquid-optics { visibility: hidden; }\r\n.ew-liquid-solid {\r\n  background: var(--ew-glass-solid, #0f2530);\r\n  opacity: calc(1 - var(--ew-liquid));\r\n  box-shadow: inset 0 0 0 1px #b9d3da47, inset 0 1px 0 #ffffff19;\r\n}\r\n.ew-liquid-rim {\r\n  opacity: var(--ew-liquid);\r\n  background: linear-gradient(175deg, #ffffff0d, transparent 45%, #112e3510);\r\n  box-shadow: inset 0 1px 1px #ffffff40, inset 0 -1px 1px #17313920;\r\n}\r\n.ew-liquid-rim::before {\r\n  content: ''; position: absolute; inset: 0; padding: 1px; border-radius: inherit;\r\n  opacity: var(--ew-rim-energy, .42);\r\n  background: conic-gradient(from 135deg, #ffffffd9, #ffffff15 16%, #5d87784d 27%, #ffffff10 40%, #ffffffe8 52%, #ffffff20 65%, #283d4d66 79%, #ffffff15 90%, #ffffffd9);\r\n  mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);\r\n  -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);\r\n  -webkit-mask-composite: xor;\r\n  mask-composite: exclude;\r\n}\r\n.ew-liquid-light { width: 100%; height: 100%; opacity: 0; }\r\n.ew-glass-header .ew-brand, .ew-glass-header .ew-menu-toggle, .ew-glass-header .ew-header__cta { position: relative; z-index: 1; }\r\n.ew-glass-header .ew-nav { z-index: 1; }\r\n.ew-glass-header .ew-nav a { position: relative; }\r\n.ew-glass-header .ew-header__inner a, .ew-glass-header .ew-menu-toggle { touch-action: pan-y; }\r\n.ew-glass-header .ew-header__inner [data-glass-tone=\"light\"] { color: #163435; text-shadow: 0 1px 3px #ffffffb0; }\r\n.ew-glass-header .ew-header__inner [data-glass-tone=\"dark\"] { color: #f3faf8; text-shadow: 0 1px 3px #07121bdb; }\r\n.ew-glass-header .ew-header__cta[data-glass-tone=\"light\"] { background: #173b3cf2; color: #f1faf5; text-shadow: none; }\r\n.ew-glass-header .ew-header__cta[data-glass-tone=\"dark\"] { background: #f4faf1f2; color: #17383a; text-shadow: none; }\r\n.ew-glass-header .ew-menu-toggle[data-glass-tone=\"light\"] { border-color: #173b3c66; }\r\n@media (max-width: 760px) {\r\n  .ew-glass-header .ew-header__inner { border-radius: var(--ew-glass-mobile-radius, 23px); }\r\n}\r\n/* Match the cinematic navigation breakpoint while retaining phone-only radii. */\r\n@media (max-width: 980px) {\r\n  .ew-glass-header .ew-nav { top: calc(100% + 10px); left: 0; right: 0; }\r\n  .ew-glass-header .ew-nav.is-open { background: #102b37; }\r\n}\r\n@media (prefers-reduced-motion: reduce) { .ew-liquid-light { display: none; } }\r\n@media (forced-colors: active) {\r\n  .ew-glass-header .ew-header__inner { background: Canvas; border: 1px solid CanvasText; }\r\n  .ew-liquid-layers { display: none; }\r\n  .ew-glass-header .ew-header__inner [data-glass-tone] { color: LinkText; text-shadow: none; }\r\n}\r\n";
